// sumOfPowers returns sum_{i=1}^{k} d^i mod mod
// where d is the prime power base
func sumOfPowers(d, k int64) int64 {
	// We need sum_{i=1}^{k} d^i mod mod
	// This is a geometric series: d * (d^k - 1) / (d - 1)
	// But we need to handle modulo arithmetic carefully
	// Since mod is prime, we can use modular inverse

	if k == 0 {
		return 0
	}

	dMod := d % mod
	if dMod == 1 {
		return k % mod
	}

	// Compute d^k mod mod
	dk := modPow(dMod, k, mod)

	// numerator = d * (d^k - 1) mod mod
	numerator := (dMod * ((dk - 1 + mod) % mod)) % mod

	// denominator = (d - 1) mod mod
	denom := (dMod - 1 + mod) % mod

	// modular inverse of denom
	denomInv := modPow(denom, mod-2, mod)

	return (numerator * denomInv) % mod
}

